@icontract.snapshot(lambda adj_list: [row[:] for row in adj_list], name="adj")
@icontract.ensure(lambda OLD, adj_list: adj_list == OLD.adj)
@icontract.ensure(lambda OLD, result: result == any(
    all(not OLD.adj[i][i] for i in range(len(OLD.adj))) and
    all((not OLD.adj[i][j]) or (colors[i] != colors[j])
        for i in range(len(OLD.adj)) for j in range(len(OLD.adj)))
    for colors in __import__('itertools').product([0, 1], repeat=len(OLD.adj))
))
@icontract.ensure(lambda OLD, result: (not any(OLD.adj[i][i] for i in range(len(OLD.adj)))) or (not result))
